28  export function errorMiddleware(error, _req, res, _next) {
29    let status = error instanceof HttpError ? error.status : 500;
30    let message = error instanceof HttpError ? error.message : 'Ocurrió un error inesperado. Inténtelo nuevamente.';
31    if (error.type === 'entity.parse.failed') { status = 400; message = 'El contenido JSON no es válido.'; }
32    if (error.type === 'entity.too.large') { status = 413; message = 'El contenido supera el tamaño permitido.'; }
33    // Códigos extendidos de SQLite: no se adivina el tipo mediante texto del error.
34    if (error.code === 'ERR_SQLITE_ERROR') {
35      if ([1555, 2067].includes(error.errcode)) { status = 409; message = 'Ya existe un registro con esos datos.'; }
36      if (error.errcode === 787) { status = 409; message = 'El registro relacionado no existe o está en uso.'; }
37      if (error.errcode === 275) { status = 422; message = 'Los datos no cumplen las restricciones del registro.'; }
38      if ([5, 6].includes(error.errcode & 255)) { status = 503; message = 'La base de datos está ocupada. Inténtelo nuevamente.'; }
39    }
40    if (error instanceof HttpError && error.retryAfter) res.set('Retry-After', String(error.retryAfter));
41    if (status === 500) console.error('Error de API:', error);
42    res.status(status).json({ error: { message, ...(error instanceof HttpError && error.fields ? { fields: error.fields } : {}) } });
43  }
